D["g1200"]={"id":"g1200","kind":"book","title":{"en":"Gargantua and Pantagruel","tr":"Gargantua ve Pantagruel"},"authors":["François Rabelais","Gustave Doré","Peter Anthony Motteux"],"source":"Project Gutenberg — eBook #1200","year":null,"level":"C2","words":194869,"minutes":1083,"blurb":{"tr":"Dev kral Gargantua ile oğlu Pantagruel'in doğumu, eğitimi, savaşları ve yolculukları üzerinden kilise, hukuk ve okul düzeni alaya alınır. Kaba şakalar, sayfalar süren listeler ve uydurma sözcüklerle dolu taşkın bir mizah kitabıdır. Urquhart ile Motteux'nün çevirisi eski İngilizceyle yapılmış ve kelime oyunlarıyla yüklüdür, ileri seviye ister."},"cover":{"emoji":"🎭","hue":210},"__file":"g1200.js","__stub":true};
D["g121"]={"id":"g121","kind":"book","title":{"en":"Northanger Abbey","tr":"Northanger Manastırı"},"authors":["Jane Austen"],"source":"Project Gutenberg — eBook #121","year":null,"level":"C1","words":77534,"minutes":431,"blurb":{"tr":"Gotik romanlara düşkün genç Catherine Morland, Bath şehrine gider, orada tanıştığı aileyle Northanger Manastırı'na davet edilir ve okuduğu korku hikâyelerinin etkisiyle evin içinde karanlık sırlar aramaya başlar. Austen bu kitapta dönemin korku romanı modasıyla alay eder. Cümleler uzun ve ince alayla yüklü, ironiyi yakalamak zaman ister."},"cover":{"emoji":"🕯️","hue":210},"__file":"g121.js","__stub":true};
D["g1212"]={"id":"g1212","kind":"book","title":{"en":"Love and Freindship [sic]","tr":"Aşk ve Dostluk"},"authors":["Jane Austen"],"source":"Project Gutenberg — eBook #1212","year":null,"level":"C1","words":33667,"minutes":187,"blurb":{"tr":"On beş yaşındaki Jane Austen'ın mektup biçiminde yazdığı kısa parodiyi ve gençlik defterlerinde kalan öteki denemelerini bir araya getiren derleme. Dönemin duygusal romanlarındaki bayılma, kaçma ve rastlantı klişeleriyle acımasızca dalga geçer. Özgün yazım hataları bilerek korunmuştur; cümleler uzun ve alaycı olduğu için mizahı yakalamak ileri düzey İngilizce ister."},"cover":{"emoji":"🎭","hue":210},"__file":"g1212.js","__stub":true};
D["g1251"]={"id":"g1251","kind":"book","title":{"en":"Le Morte d'Arthur: Volume 1","tr":"Kral Arthur'un Ölümü: 1. Cilt"},"authors":["Thomas Malory"],"source":"Project Gutenberg — eBook #1251","year":null,"level":"C2","words":163748,"minutes":910,"blurb":{"tr":"Arthur'un doğuşundan kral oluşuna, Yuvarlak Masa'nın kurulmasından şövalyelerin maceralarına uzanan Arthur efsanelerinin on beşinci yüzyılda derlenmiş hâli. Birinci cilt turnuvalar, büyücü Merlin ve şövalye görevleriyle geçer. Metin dönemin İngilizcesiyle yazılmış: cümle dizilişi bugünküne benzemiyor, eski sözcükler ve tekrarlar sık."},"cover":{"emoji":"🐉","hue":210},"__file":"g1251.js","__stub":true};
D["g1259"]={"id":"g1259","kind":"book","title":{"en":"Twenty years after","tr":"Yirmi Yıl Sonra"},"authors":["Alexandre Dumas","Auguste Maquet"],"source":"Project Gutenberg — eBook #1259","year":null,"level":"C1","words":243228,"minutes":1351,"blurb":{"tr":"Üç Silahşorlar'ın devamı. Aradan yirmi yıl geçmiş, dört arkadaş dağılmıştır; Fransa'daki iç karışıklıkta ve İngiltere'de kralın idamına giden olaylarda birbirlerinin karşı tarafında yeniden buluşurlar. Siyasi entrika, kaçırma ve düello sahneleri birbirini kovalar. Fransızcadan çevrilmiş uzun bir kitaptır; unvanlar ve dönemin siyasi adları takibi zorlaştırır."},"cover":{"emoji":"⛵","hue":210},"__file":"g1259.js","__stub":true};
D["g1260"]={"id":"g1260","kind":"book","title":{"en":"Jane Eyre: An Autobiography","tr":"Jane Eyre"},"authors":["Charlotte Brontë","F. H. (Frederick Henry) Townsend"],"source":"Project Gutenberg — eBook #1260","year":null,"level":"C1","words":186456,"minutes":1036,"blurb":{"tr":"Öksüz büyüyen, sert bir yatılı okulda yetişen Jane Eyre, Thornfield Malikânesi'ne mürebbiye olarak girer ve evin sahibi Bay Rochester'la arasında beklenmedik bir yakınlık kurulur. Ancak evin çatı katında saklanan bir sır her şeyi altüst eder. Kitap birinci ağızdan yazılmıştır ve yer yer doğrudan okura seslenir. Cümleler uzun ve edebidir; araya Fransızca replikler ve yöresel ağız girer."},"cover":{"emoji":"🌹","hue":210},"__file":"g1260.js","__stub":true};
D["g1268"]={"id":"g1268","kind":"book","title":{"en":"The Mysterious Island","tr":"Esrarengiz Ada"},"authors":["Jules Verne","Agnes Kinloch Kingston"],"source":"Project Gutenberg — eBook #1268","year":null,"level":"B2","words":193202,"minutes":1073,"blurb":{"tr":"Amerikan İç Savaşı sırasında bir balonla kaçan beş kişi, Pasifik'te ıssız bir adaya düşer; neredeyse hiçbir şeyleri yokken tuğla, cam, barut ve telgraf üretip küçük bir uygarlık kurarlar. Zamanla adada onlara gizlice yardım eden birinin varlığı ortaya çıkar. Teknik ve kimya açıklamaları ayrıntılıdır; onun dışında anlatım düz ve takip etmesi kolaydır."},"cover":{"emoji":"🪐","hue":210},"__file":"g1268.js","__stub":true};
D["g1279"]={"id":"g1279","kind":"book","title":{"en":"Poems and Songs of Robert Burns","tr":"Robert Burns'ün Şiirleri ve Şarkıları"},"authors":["Robert Burns"],"source":"Project Gutenberg — eBook #1279","year":null,"level":"C2","words":128285,"minutes":713,"blurb":{"tr":"İskoçya'nın ulusal şairi sayılan Robert Burns'ün şiirleri ve şarkı sözleri bir arada. Kır hayatı, aşk, içki sofraları, yoksulluk ve dostluk üzerine yüzlerce parça var; aralarında Auld Lang Syne gibi bugün hâlâ söylenen şarkılar da bulunuyor. Metinlerin çoğu İskoç ağzıyla yazılmış, sözlük ve açıklama olmadan takip etmek çok zor."},"cover":{"emoji":"🪶","hue":210},"__file":"g1279.js","__stub":true};
D["g1342"]={"id":"g1342","kind":"book","title":{"en":"Pride and Prejudice","tr":"Aşk ve Gurur"},"authors":["Jane Austen"],"source":"Project Gutenberg — eBook #1342","year":null,"level":"C1","words":122334,"minutes":680,"blurb":{"tr":"Taşrada yaşayan Bennet ailesinin beş kızı vardır ve anneleri hepsini iyi bir evlilikle yerleştirmeye çalışır. Keskin zekâlı Elizabeth ile varlıklı ama mesafeli Bay Darcy, önyargılarını aşana kadar birbirlerini yanlış tanır. Roman dönemin miras, gelir ve sınıf hesaplarını da anlatır. Austen'ın cümleleri uzun ve alaycıdır, asıl anlam çoğu zaman satır aralarındadır."},"cover":{"emoji":"🌹","hue":210},"__file":"g1342.js","__stub":true};
D["g135"]={"id":"g135","kind":"book","title":{"en":"Les Misérables","tr":"Sefiller"},"authors":["Victor Hugo","Isabel Florence Hapgood"],"source":"Project Gutenberg — eBook #135","year":null,"level":"C2","words":564740,"minutes":3137,"blurb":{"tr":"Bir somun ekmek çaldığı için on dokuz yıl kürek cezası çeken Jean Valjean, tahliyesinden sonra kimliğini değiştirip yeni bir hayat kurar, ama müfettiş Javert peşini bırakmaz. Fantine'in düşüşü, küçük Cosette'in kurtarılışı ve 1832 Paris ayaklanması aynı hikâyede birleşir. Roman çok uzun; Waterloo, Paris lağımları ve manastır düzeni gibi konularda uzun ara bölümler var."},"cover":{"emoji":"🏛️","hue":210},"__file":"g135.js","__stub":true};
D["g1353"]={"id":"g1353","kind":"book","title":{"en":"Off on a Comet! a Journey through Planetary Space","tr":"Kuyruklu Yıldızda Yolculuk"},"authors":["Jules Verne"],"source":"Project Gutenberg — eBook #1353","year":null,"level":"C1","words":100096,"minutes":556,"blurb":{"tr":"Akdeniz kıyısına sürtünen bir kuyruklu yıldız, toprağın bir parçasını ve üstündeki avuç dolusu insanı da alıp uzaya taşır. Kahramanlar bu küçük gök cismi üzerinde hayatta kalmaya ve Güneş Sistemi'ni dolaşan yörüngeyi hesaplamaya çalışır. Verne'in alışıldık üslubu geçerli: bol astronomi açıklaması ve uzun betimleme paragrafları."},"cover":{"emoji":"🪐","hue":210},"__file":"g1353.js","__stub":true};
D["g139"]={"id":"g139","kind":"book","title":{"en":"The Lost World","tr":"Kayıp Dünya"},"authors":["Arthur Conan Doyle"],"source":"Project Gutenberg — eBook #139","year":null,"level":"B2","words":75569,"minutes":420,"blurb":{"tr":"Genç gazeteci Malone, aksi ve gürültücü Profesör Challenger'ın Güney Amerika'da dinozorların yaşadığı bir yayla bulduğu iddiasını doğrulamak için sefere katılır. Ekip yaylaya çıktığında dönüş yolunu kaybeder. Cümleler orta uzunlukta ve olaylar hızlı akıyor; asıl zorluk bilimsel tartışma bölümlerindeki terimlerde."},"cover":{"emoji":"🪐","hue":210},"__file":"g139.js","__stub":true};
D["g1400"]={"id":"g1400","kind":"book","title":{"en":"Great Expectations","tr":"Büyük Umutlar"},"authors":["Charles Dickens"],"source":"Project Gutenberg — eBook #1400","year":null,"level":"C1","words":185471,"minutes":1030,"blurb":{"tr":"Bataklık kıyısındaki bir köyde ablasının yanında büyüyen yetim Pip, kaçak bir mahkûma yiyecek götürür; yıllar sonra adını bilmediği biri ona servet bırakınca Londra'ya gidip kibar bir beyefendi olmaya çalışır. Zenginlik, sınıf atlama ve minnet üzerine acı bir hesaplaşma. Dickens'ın cümleleri uzun ve mecazlı, demirci Joe gibi kişiler halk ağzıyla konuştuğu için o satırlar yavaş okunur."},"cover":{"emoji":"📗","hue":210},"__file":"g1400.js","__stub":true};
D["g14244"]={"id":"g14244","kind":"book","title":{"en":"The Romance of Tristan and Iseult","tr":"Tristan ile İzolde"},"authors":["Joseph Bédier","Hilaire Belloc"],"source":"Project Gutenberg — eBook #14244","year":null,"level":"B2","words":25814,"minutes":143,"blurb":{"tr":"Ortaçağın en ünlü aşk efsanesinin dağınık parçalarından derlenip yeniden anlatılmış hâli. Kral Mark'ın yeğeni Tristan ile kralın gelini İzolde, yanlışlıkla içtikleri aşk iksiri yüzünden birbirlerine bağlanır ve bu bağ ikisini de sona sürükler. Belloc'un çevirisi kısa cümlelerle, masalsı ve törensel bir dille yazılmıştır; sözcükler zor değil ama üslup eskidir."},"cover":{"emoji":"🐉","hue":210},"__file":"g14244.js","__stub":true};
D["g145"]={"id":"g145","kind":"book","title":{"en":"Middlemarch","tr":"Middlemarch"},"authors":["George Eliot"],"source":"Project Gutenberg — eBook #145","year":null,"level":"C2","words":318342,"minutes":1769,"blurb":{"tr":"On dokuzuncu yüzyıl İngiltere'sinde bir taşra kasabasının hayatı: idealist Dorothea'nın yaşlı bir bilginle yaptığı hatalı evlilik, genç doktor Lydgate'in borç ve dedikodu yüzünden çöküşü, seçim ve miras kavgaları iç içe ilerler. Anlatıcı sık sık durup uzun ahlak ve psikoloji yorumları yapar. Çok uzun cümleleri ve soyut sözcük dağarcığıyla en ağır klasiklerden biridir."},"cover":{"emoji":"📗","hue":210},"__file":"g145.js","__stub":true};
D["g146"]={"id":"g146","kind":"book","title":{"en":"A Little Princess","tr":"Küçük Prenses"},"authors":["Frances Hodgson Burnett"],"source":"Project Gutenberg — eBook #146","year":null,"level":"B1","words":66316,"minutes":368,"blurb":{"tr":"Hindistan'dan getirilip Londra'daki pahalı bir yatılı okula yerleştirilen varlıklı Sara Crewe, babası ölüp parasız kalınca aynı okulda hizmetçi olarak çalıştırılır. Tavan arasında yaşarken hayal kurma alışkanlığı ve nezaketi sayesinde ayakta kalır. Anlatım akıcı, ancak hizmetçi kızın konuşmaları Londra halk ağzıyla yazıldığı için o satırlar zorlayabilir."},"cover":{"emoji":"🧸","hue":210},"__file":"g146.js","__stub":true};
D["g14860"]={"id":"g14860","kind":"book","title":{"en":"The Journal of Sir Walter Scott","tr":"Sir Walter Scott'ın Günlüğü"},"authors":["Walter Scott","David Douglas"],"source":"Project Gutenberg — eBook #14860","year":null,"level":"C1","words":320904,"minutes":1783,"blurb":{"tr":"Ünlü romancının 1825'ten ölümüne kadar tuttuğu günlük. Ortağı olduğu yayıncılığın batmasıyla büyük bir borcun altına giren Scott'ın, borcunu ödemek için hasta hasta roman yazışını, eşinin ölümünü ve gündelik uğraşlarını kendi kaleminden okuruz. Günlük olduğu için metin not biçiminde, kısaltmalı ve dönemin kişilerine göndermelerle doludur."},"cover":{"emoji":"📗","hue":210},"__file":"g14860.js","__stub":true};
D["g149"]={"id":"g149","kind":"book","title":{"en":"The Lost Continent","tr":"Kayıp Kıta"},"authors":["Edgar Rice Burroughs"],"source":"Project Gutenberg — eBook #149","year":null,"level":"B2","words":37923,"minutes":211,"blurb":{"tr":"İki yüzyıldır Avrupa ile bütün bağını kesmiş bir Amerika'dan gelen deniz subayı, kazara yasak sınırın ötesine geçer ve eski uygarlığın savaşlar sonunda çöküp yerini yabanıl bir hayata bıraktığını görür. Burroughs'un savaş yıllarında yazdığı kısa bir gelecek tasviri. Metin kısa ve hızlı; değişime uğramış yer adlarını çözmek biraz dikkat istiyor."},"cover":{"emoji":"🪐","hue":210},"__file":"g149.js","__stub":true};
D["g1510"]={"id":"g1510","kind":"book","title":{"en":"Love's Labour's Lost","tr":"Aşkın Çabası Boşuna"},"authors":["William Shakespeare"],"source":"Project Gutenberg — eBook #1510","year":null,"level":"C2","words":22569,"minutes":125,"blurb":{"tr":"Navarra kralı ve üç soylu arkadaşı üç yıl boyunca kitaplara gömülüp kadınlardan uzak duracaklarına yemin eder. Fransa prensesi ile nedimeleri saraya gelince yeminler birer birer bozulur; gizli mektuplar, kılık değiştirmeler ve söz oyunlarıyla dolu bir komedi başlar. Oyun Shakespeare'in en çok kelime oyunu içeren metinlerindendir, notsuz bir baskıyla okumak neredeyse imkânsızdır."},"cover":{"emoji":"🎭","hue":210},"__file":"g1510.js","__stub":true};
D["g1513"]={"id":"g1513","kind":"book","title":{"en":"Romeo and Juliet","tr":"Romeo ve Juliet"},"authors":["William Shakespeare"],"source":"Project Gutenberg — eBook #1513","year":null,"level":"C2","words":25858,"minutes":144,"blurb":{"tr":"Verona'da yıllardır düşman olan iki ailenin çocukları Romeo ile Juliet, tanıştıkları gece âşık olur ve gizlice evlenir. Sokak kavgaları, bir sürgün kararı ve zamanında ulaşmayan bir haber ikisini de yıkıma götürür. Oyun manzum yazılmıştır ve söz oyunlarıyla doludur. Erken modern İngilizce kullanıldığı için açıklamalı bir baskıyla, tercihen sahne çevirisi yanınızda okumak gerekir."},"cover":{"emoji":"🌹","hue":210},"__file":"g1513.js","__stub":true};
D["g1514"]={"id":"g1514","kind":"book","title":{"en":"A Midsummer Night's Dream","tr":"Bir Yaz Gecesi Rüyası"},"authors":["William Shakespeare"],"source":"Project Gutenberg — eBook #1514","year":null,"level":"C2","words":17261,"minutes":96,"blurb":{"tr":"Atina yakınındaki bir ormanda birbirini kovalayan dört gencin, oyun hazırlayan bir grup esnafın ve kavgalı peri kral ile kraliçesinin yolları kesişir. Bir çiçek özüyle yapılan büyü kimin kime âşık olduğunu karıştırınca gece boyunca komik bir karmaşa yaşanır. Metin manzum ve on altıncı yüzyıl İngilizcesiyledir; açıklama notları olan bir baskı olmadan izlemek çok güçtür."},"cover":{"emoji":"🪐","hue":210},"__file":"g1514.js","__stub":true};
D["g1523"]={"id":"g1523","kind":"book","title":{"en":"As You Like It","tr":"Nasıl Hoşunuza Giderse"},"authors":["William Shakespeare"],"source":"Project Gutenberg — eBook #1523","year":null,"level":"C2","words":23053,"minutes":128,"blurb":{"tr":"Saraydan sürülen Rosalind erkek kılığına girip Arden Ormanı'na sığınır; ormanda âşıklar, soytarılar ve sürgün soylular birbirine karışır, oyun birkaç düğünle biter. Bütün dünyanın bir sahne olduğunu söyleyen ünlü tirat da bu oyundandır. Manzum yazılmış bir tiyatro metnidir; on altıncı yüzyıl İngilizcesi ve kelime oyunları yüzünden açıklamalı bir baskı şarttır."},"cover":{"emoji":"🌹","hue":210},"__file":"g1523.js","__stub":true};
