D["g155"]={"id":"g155","kind":"book","title":{"en":"The Moonstone","tr":"Aytaşı"},"authors":["Wilkie Collins"],"source":"Project Gutenberg — eBook #155","year":null,"level":"C1","words":194260,"minutes":1079,"blurb":{"tr":"Hindistan'daki bir tapınaktan yağmalanan sarı bir elmas, genç bir kadına doğum günü armağanı olarak verilir ve aynı gece kaybolur. Olay, uşaktan avukata kadar farklı kişilerin kaleme aldığı ifadelerle, her biri kendi bakış açısından anlatılır. Anlatıcıların üslubu ayrı olduğundan dil bölümden bölüme değişiyor; kitap uzun ve ayrıntı yoğun."},"cover":{"emoji":"🔍","hue":210},"__file":"g155.js","__stub":true};
D["g1564"]={"id":"g1564","kind":"book","title":{"en":"Boswell's Life of Johnson","tr":"Samuel Johnson'ın Hayatı"},"authors":["James Boswell","Charles Grosvenor Osgood"],"source":"Project Gutenberg — eBook #1564","year":null,"level":"C2","words":217113,"minutes":1206,"blurb":{"tr":"James Boswell'in, yıllarca yakınında bulunduğu sözlük yazarı Samuel Johnson'ı anlattığı ünlü biyografi. Johnson'ın çocukluğundan ölümüne kadarki hayatını, çalışma alışkanlıklarını ve özellikle sofra sohbetlerindeki keskin cevaplarını kaydeder. On sekizinci yüzyıl İngilizcesi resmi ve ağır; kitap uzun, ama sohbet bölümleri tek tek okunabilir."},"cover":{"emoji":"📗","hue":210},"__file":"g1564.js","__stub":true};
D["g1597"]={"id":"g1597","kind":"book","title":{"en":"Andersen's Fairy Tales","tr":"Andersen Masalları"},"authors":["H. C. (Hans Christian) Andersen"],"source":"Project Gutenberg — eBook #1597","year":null,"level":"B1","words":55338,"minutes":307,"blurb":{"tr":"Çirkin Ördek Yavrusu, Kibritçi Kız, Küçük Deniz Kızı ve Kralın Yeni Giysileri gibi tanınmış masalların bir araya getirildiği derleme. Andersen'in hikâyeleri çoğu zaman hüzünlü biter ve çocuk kadar yetişkine de seslenir. Masallar kısa olduğu için tek oturuşta bitiyor, dil sade; yalnızca eski masal kalıpları dikkat ister."},"cover":{"emoji":"🧸","hue":210},"__file":"g1597.js","__stub":true};
D["g16"]={"id":"g16","kind":"book","title":{"en":"Peter Pan","tr":"Peter Pan"},"authors":["J. M. (James Matthew) Barrie"],"source":"Project Gutenberg — eBook #16","year":null,"level":"B2","words":47260,"minutes":263,"blurb":{"tr":"Büyümeyi reddeden Peter Pan bir gece Londra'daki Darling ailesinin çocuk odasına girer ve Wendy ile iki kardeşini Neverland'e götürür; orada kayıp çocuklar, deniz kızları ve Kaptan Hook'un korsanları vardır. Anlatıcı sık sık araya girip okurla konuşur; bu şakacı ara sözler ve devrik cümleler dili beklenenden zorlaştırır."},"cover":{"emoji":"⛵","hue":210},"__file":"g16.js","__stub":true};
D["g160"]={"id":"g160","kind":"book","title":{"en":"The Awakening, and Selected Short Stories","tr":"Uyanış ve Seçme Öyküler"},"authors":["Kate Chopin"],"source":"Project Gutenberg — eBook #160","year":null,"level":"B2","words":64477,"minutes":358,"blurb":{"tr":"Louisiana'da varlıklı bir kocayla sıkışmış bir hayat süren Edna Pontellier, bir yaz tatilinde kendi istekleri, resim yapma arzusu ve başka bir adama duyduğu ilgiyle uyanır; toplumun ona biçtiği eş ve anne rolünden uzaklaşır. Cilde yazarın kısa öyküleri de eklenmiştir. Roman kısa ve akıcı; ancak araya Fransızca sözler ve yerel şive giriyor."},"cover":{"emoji":"📗","hue":210},"__file":"g160.js","__stub":true};
D["g1608"]={"id":"g1608","kind":"book","title":{"en":"Camille (La Dame aux Camilias)","tr":"Kamelyalı Kadın"},"authors":["Alexandre Dumas"],"source":"Project Gutenberg — eBook #1608","year":null,"level":"C1","words":66526,"minutes":370,"blurb":{"tr":"Paris'in ünlü hayat kadınlarından Marguerite Gautier ile ona âşık olan genç Armand Duval'in imkânsız ilişkisini anlatır; hikâye, kadının ölümünden sonra eşyalarının açık artırmayla satılmasıyla açılır. Fransızcadan çevrilmiş, duygusal ve konuşma ağırlıklı bir metindir; cümleler çok uzun değildir ama dönemin toplumsal imaları arada anlaşılmayabilir."},"cover":{"emoji":"🌹","hue":210},"__file":"g1608.js","__stub":true};
D["g161"]={"id":"g161","kind":"book","title":{"en":"Sense and Sensibility","tr":"Akıl ve Tutku"},"authors":["Jane Austen"],"source":"Project Gutenberg — eBook #161","year":null,"level":"C1","words":119693,"minutes":665,"blurb":{"tr":"Babalarının ölümüyle yoksullaşan Dashwood kız kardeşler, ölçülü Elinor ile duygularını hiç saklamayan Marianne, taşrada yeni bir hayat kurarken evlilik, para ve kalp kırıklığıyla sınanır. Austen aklın ve tutkunun hangisinin insanı koruduğunu ince bir alayla tartışır. Cümleler uzun ve dolaylı, miras ile görgü kurallarına ilişkin dönem sözcükleri sık geçiyor."},"cover":{"emoji":"🌹","hue":210},"__file":"g161.js","__stub":true};
D["g16328"]={"id":"g16328","kind":"book","title":{"en":"Beowulf: An Anglo-Saxon Epic Poem","tr":"Beowulf: Bir Anglosakson Destanı"},"authors":["J. Lesslie (John Lesslie) Hall"],"source":"Project Gutenberg — eBook #16328","year":null,"level":"C2","words":34328,"minutes":191,"blurb":{"tr":"Anglosaksonların en eski destanı. Kahraman Beowulf, Danimarka kralının salonunu basan canavar Grendel'i, ardından Grendel'in annesini öldürür; yıllar sonra kendi ülkesinin kralıyken bir ejderhayla son kez dövüşür. Hall'ın çevirisi özgün şiirin aliterasyonlu ölçüsünü taklit eder; bileşik sözcükler ve eskimiş kalıplar yüzünden İngilizcesi son derece ağırdır."},"cover":{"emoji":"🐉","hue":210},"__file":"g16328.js","__stub":true};
D["g16389"]={"id":"g16389","kind":"book","title":{"en":"The Enchanted April","tr":"Büyülü Nisan"},"authors":["Elizabeth Von Arnim"],"source":"Project Gutenberg — eBook #16389","year":null,"level":"B2","words":78706,"minutes":437,"blurb":{"tr":"Yağmurlu ve kasvetli bir Londra kışının ardından, birbirini tanımayan dört İngiliz kadın bir gazete ilanına uyup İtalya kıyısındaki bir ortaçağ şatosunu nisan ayı boyunca kiralar. Orada geçirdikleri bu bir ay, dördünün de hayata bakışını değiştirir. Olay örgüsü sakindir; cümleler uzun ve iç konuşmalarla doludur, ama sözcükler ağır değildir."},"cover":{"emoji":"📗","hue":210},"__file":"g16389.js","__stub":true};
D["g164"]={"id":"g164","kind":"book","title":{"en":"Twenty Thousand Leagues under the Sea","tr":"Denizler Altında Yirmi Bin Fersah"},"authors":["Jules Verne"],"source":"Project Gutenberg — eBook #164","year":null,"level":"B2","words":104556,"minutes":581,"blurb":{"tr":"Denizlerde görülen esrarengiz bir yaratığın peşine düşen Profesör Aronnax ve arkadaşları, bunun aslında Kaptan Nemo'nun Nautilus adlı denizaltısı olduğunu anlar ve gemide tutsak kalır; ardından okyanusların altında dünyayı dolaşan uzun bir yolculuk başlar. Deniz canlılarının adları ve ölçüler sayfalarca sıralanır; bu listeler dışında dil akıcıdır."},"cover":{"emoji":"🪐","hue":210},"__file":"g164.js","__stub":true};
D["g1661"]={"id":"g1661","kind":"book","title":{"en":"The Adventures of Sherlock Holmes","tr":"Sherlock Holmes'un Maceraları"},"authors":["Arthur Conan Doyle"],"source":"Project Gutenberg — eBook #1661","year":null,"level":"B2","words":104486,"minutes":580,"blurb":{"tr":"Dr. Watson'ın kaleminden, Baker Street'te oturan dedektif Sherlock Holmes'un çözdüğü on iki vakayı toplayan öykü kitabı. Şantaj için saklanan bir fotoğraf, tuhaf bir iş ilanı ve düğün günü kaybolan bir gelin gibi olaylar hep küçük ayrıntılardan çözülür. Öyküler birbirinden bağımsız ve kısa olduğu için ara verip devam etmek kolaydır; Viktorya dönemi eşya adları sözlük gerektirebilir."},"cover":{"emoji":"🔍","hue":210},"__file":"g1661.js","__stub":true};
D["g1695"]={"id":"g1695","kind":"book","title":{"en":"The Man Who Was Thursday: A Nightmare","tr":"Perşembe Adlı Adam: Bir Kâbus"},"authors":["G. K. (Gilbert Keith) Chesterton"],"source":"Project Gutenberg — eBook #1695","year":null,"level":"C2","words":58261,"minutes":324,"blurb":{"tr":"Şair kılığında çalışan polis Gabriel Syme, her üyesi haftanın bir gününün adını taşıyan gizli bir anarşist konseyine sızar ve Perşembe olur. Kovalamacalar ilerledikçe kimin gerçekten kim olduğu bulanıklaşır, kitap polisiyeden felsefi bir kâbusa döner. Chesterton paradokslarla ve şaşırtıcı benzetmelerle yazar; olay örgüsü basit olsa da dili ileri düzey okuma ister."},"cover":{"emoji":"🔍","hue":210},"__file":"g1695.js","__stub":true};
D["g17157"]={"id":"g17157","kind":"book","title":{"en":"Gulliver's Travels into Several Remote Regions of the World","tr":"Gulliver'in Gezileri"},"authors":["Jonathan Swift","Thomas M. (Thomas Minard) Balliet"],"source":"Project Gutenberg — eBook #17157","year":null,"level":"C1","words":51674,"minutes":287,"blurb":{"tr":"Gemi doktoru Lemuel Gulliver'ın dört ayrı yolculuğunda başına gelenler: avuç içi kadar insanların ülkesi, devler ülkesi, uçan ada ve atların akıllı, insanların hayvan sayıldığı ülke. Çocuk kitabı gibi anılsa da metin dönemin siyaseti ve insan doğası üzerine sert bir yergidir. On sekizinci yüzyıl İngilizcesiyle yazılmıştır; cümleler uzun, bazı sözcükler bugün kullanılmıyor."},"cover":{"emoji":"🪐","hue":210},"__file":"g17157.js","__stub":true};
D["g1719"]={"id":"g1719","kind":"book","title":{"en":"The Ballad of the White Horse","tr":"Beyaz Atın Baladı"},"authors":["G. K. (Gilbert Keith) Chesterton"],"source":"Project Gutenberg — eBook #1719","year":null,"level":"C2","words":16269,"minutes":90,"blurb":{"tr":"Chesterton'ın uzun anlatı şiiri, Kral Alfred'in Danimarkalı istilacılara karşı verdiği umutsuz mücadeleyi ve Ethandune'daki çarpışmayı anlatır. Tarihten çok efsane havasında ilerler; savaş sahneleri, kehanetler ve inanç üzerine bölümlerle örülüdür. Dizeler kafiyeli ve imgelerle yüklü olduğundan İngilizcesi ağırdır, yavaş okumak gerekir."},"cover":{"emoji":"🐉","hue":210},"__file":"g1719.js","__stub":true};
D["g1727"]={"id":"g1727","kind":"book","title":{"en":"The Odyssey","tr":"Odysseia"},"authors":["751? BCE-651? BCE Homer","Samuel Butler"],"source":"Project Gutenberg — eBook #1727","year":null,"level":"B2","words":126497,"minutes":703,"blurb":{"tr":"Truva Savaşı bittikten sonra Odysseus'un on yıl süren eve dönüş yolculuğu. Tek gözlü dev, büyücü Kirke ve sirenler gibi engeller onu yolundan alıkoyarken, İthake'de karısı Penelope evi basan talipleri oyalamaya çalışır. Bu baskı Samuel Butler'ın düzyazı çevirisidir. Şiir değil düz metin olduğu için akıcıdır, ama Yunan tanrı ve yer adlarının çokluğuna alışmak gerekir."},"cover":{"emoji":"🐉","hue":210},"__file":"g1727.js","__stub":true};
D["g174"]={"id":"g174","kind":"book","title":{"en":"The Picture of Dorian Gray","tr":"Dorian Gray'in Portresi"},"authors":["Oscar Wilde"],"source":"Project Gutenberg — eBook #174","year":null,"level":"C1","words":78774,"minutes":438,"blurb":{"tr":"Genç ve güzel Dorian Gray, portresi yapıldıktan sonra yaşlanmanın kendisi yerine tabloya geçmesini diler ve dileği gerçek olur. Yıllar boyunca yüzü hiç değişmezken tavan arasında sakladığı resim onun her kötülüğüyle biraz daha çirkinleşir. Diyaloglar nükteli ve iğneleyici; cümleler çok uzun değil, ama söz oyunları ilk okuyuşta kaçabilir."},"cover":{"emoji":"🕯️","hue":210},"__file":"g174.js","__stub":true};
D["g17460"]={"id":"g17460","kind":"book","title":{"en":"Lorna Doone: A Romance of Exmoor","tr":"Lorna Doone"},"authors":["R. D. (Richard Doddridge) Blackmore"],"source":"Project Gutenberg — eBook #17460","year":null,"level":"C2","words":271787,"minutes":1510,"blurb":{"tr":"On yedinci yüzyıl İngiltere'sinde, Exmoor kırlarında yaşayan çiftçi John Ridd, babasını öldüren Doone çetesinin arasında büyüyen Lorna'ya âşık olur. Kan davası, kanun kaçakları ve dönemin ayaklanmaları hikâyeye karışır. Anlatıcı bölgenin ağzıyla konuşur; cümleler çok uzun, eski sözcükler ve yerel deyimler yoğun."},"cover":{"emoji":"🌹","hue":210},"__file":"g17460.js","__stub":true};
D["g175"]={"id":"g175","kind":"book","title":{"en":"The Phantom of the Opera","tr":"Operadaki Hayalet"},"authors":["Gaston Leroux"],"source":"Project Gutenberg — eBook #175","year":null,"level":"B2","words":82752,"minutes":460,"blurb":{"tr":"Paris Operası'nın çalışanları, binanın altındaki galerilerde yaşayan ve kendisine para ile ayrıcalık ödenmesini isteyen bir hayaletten söz eder. Yüzü korkunç biçimde biçimsiz olan Erik, genç şarkıcı Christine Daaé'yi gizlice yetiştirir ve ona saplantıyla bağlanır. Fransızcadan çevrilen metin gazete soruşturması havasında ilerliyor; bölümler kısa, dil çoğunlukla anlaşılır."},"cover":{"emoji":"🔍","hue":210},"__file":"g175.js","__stub":true};
D["g1837"]={"id":"g1837","kind":"book","title":{"en":"The Prince and the Pauper","tr":"Prens ve Dilenci"},"authors":["Mark Twain"],"source":"Project Gutenberg — eBook #1837","year":null,"level":"C1","words":68850,"minutes":383,"blurb":{"tr":"On altıncı yüzyıl Londra'sında birbirine tıpatıp benzeyen iki çocuk, yoksul Tom Canty ile veliaht prens Edward, şaka olsun diye giysilerini değiştirir; ancak kimse değişikliği fark etmez ve gerçek prens sokaklarda kalır. Çocuk kitabı gibi görünse de konuşmalar bilerek eski İngilizceyle, 'thou' ve 'prithee' gibi kalıplarla yazılmıştır."},"cover":{"emoji":"🧸","hue":210},"__file":"g1837.js","__stub":true};
D["g18459"]={"id":"g18459","kind":"book","title":{"en":"Hypnerotomachia: The Strife of Loue in a Dreame","tr":"Hypnerotomachia: Rüyada Aşk Savaşı"},"authors":["Francesco Colonna","Robert Dallington"],"source":"Project Gutenberg — eBook #18459","year":null,"level":"C2","words":68824,"minutes":382,"blurb":{"tr":"1499'da İtalya'da basılmış, rüya biçiminde kurgulanmış ünlü bir aşk alegorisinin ilk ve kısmi İngilizce çevirisi. Anlatıcı, rüyasında sevdiği kadını ararken antik yapılar, bahçeler ve tören alaylarıyla dolu bir manzarada dolaşır; metnin büyük bölümü bu mimari betimlemelere ayrılmıştır. On altıncı yüzyıl yazımıyla, eski harf kullanımları ve çok uzun süslü cümlelerle basılmıştır."},"cover":{"emoji":"🐉","hue":210},"__file":"g18459.js","__stub":true};
D["g18575"]={"id":"g18575","kind":"book","title":{"en":"One Hundred Merrie And Delightsome Stories","tr":"Yüz Neşeli ve Hoş Hikâye"},"authors":["Robert B. (Robert Bruce) Douglas","Antoine de La Sale","Léon Lebèque"],"source":"Project Gutenberg — eBook #18575","year":null,"level":"C2","words":150989,"minutes":839,"blurb":{"tr":"On beşinci yüzyılda Burgonya sarayında derlenen yüz Fransız hikâyesinin İngilizce çevirisi. Çoğu kısa, açık saçık ve şakacı anlatılar: aldatan eşler, kurnaz rahipler, tuzağa düşürülen tüccarlar; Boccaccio'nun Decameron'una benzer bir gelenekten geliyor. Çevirmen bilerek eski İngilizceyi taklit etmiş, bu yüzden sözcükler ve cümle kuruluşu bugünün dilinden uzak."},"cover":{"emoji":"🎭","hue":210},"__file":"g18575.js","__stub":true};
D["g1874"]={"id":"g1874","kind":"book","title":{"en":"The Railway Children","tr":"Demiryolu Çocukları"},"authors":["E. (Edith) Nesbit"],"source":"Project Gutenberg — eBook #1874","year":null,"level":"B1","words":59219,"minutes":329,"blurb":{"tr":"Babaları bir gece aniden evden götürülünce anneleriyle birlikte taşraya, demiryolu hattının yanındaki küçük bir eve taşınan üç kardeşin hikâyesi. Çocuklar günlerini trenleri izleyerek, istasyondaki görevlilerle dostluk kurarak ve babalarına ne olduğunu anlamaya çalışarak geçirir. Bölümler kısa, cümleler basittir; çocuk klasikleri arasında en kolay okunanlardandır."},"cover":{"emoji":"⛵","hue":210},"__file":"g1874.js","__stub":true};
D["g18857"]={"id":"g18857","kind":"book","title":{"en":"A Journey to the Centre of the Earth","tr":"Dünyanın Merkezine Yolculuk"},"authors":["Jules Verne"],"source":"Project Gutenberg — eBook #18857","year":null,"level":"B2","words":85564,"minutes":475,"blurb":{"tr":"Alman bir profesör, eski bir el yazmasında yerin merkezine giden yolun tarifini bulur ve yeğeniyle birlikte İzlanda'daki sönmüş bir yanardağdan aşağı iner. Yol boyunca yeraltı denizleri, dev mantar ormanları ve tarih öncesi yaratıklarla karşılaşırlar. Jeoloji ve mineral adları çok geçer; bunun dışında anlatım düz, cümleler orta uzunluktadır."},"cover":{"emoji":"🪐","hue":210},"__file":"g18857.js","__stub":true};
D["g19027"]={"id":"g19027","kind":"book","title":{"en":"The Revolt on Venus","tr":"Venüs'te İsyan"},"authors":["Carey Rockwell","Willy Ley","Louis Glanzman"],"source":"Project Gutenberg — eBook #19027","year":null,"level":"B1","words":53037,"minutes":295,"blurb":{"tr":"Uzay Akademisi'nin genç kadetleri, göreve gittikleri Venüs'te bir ayaklanma planıyla karşılaşır ve gezegenin ormanlarında tehlikeli bir soruşturmanın içine çekilir. Gençler için yazılmış Tom Corbett dizisinin kitaplarından biri. Cümleler kısa, sözcük dağarcığı dar ve bol diyalog var; İngilizce okumaya yeni başlayanlara uygun."},"cover":{"emoji":"🪐","hue":210},"__file":"g19027.js","__stub":true};
D["g1934"]={"id":"g1934","kind":"book","title":{"en":"Songs of Innocence and of Experience","tr":"Masumiyet ve Tecrübe Şarkıları"},"authors":["William Blake"],"source":"Project Gutenberg — eBook #1934","year":null,"level":"B2","words":5470,"minutes":30,"blurb":{"tr":"Blake'in birbirini yanıtlayan iki şiir kümesi. İlk bölüm çocukluğun saflığını, ikinci bölüm aynı konuların yoksulluk, sömürü ve baskıyla kararmış halini anlatır; kuzu, kaplan ve baca temizleyicisi çocuklar gibi imgeler her iki tarafta da karşımıza çıkar. Şiirler kısa, kelimeler basittir; ama eskimiş zamir ve fiil çekimleri okumayı yavaşlatır."},"cover":{"emoji":"🪶","hue":210},"__file":"g1934.js","__stub":true};
D["g19412"]={"id":"g19412","kind":"book","title":{"en":"Set in Silver","tr":"Gümüşle Çevrili"},"authors":["C. N. (Charles Norris) Williamson","A. M. (Alice Muriel) Williamson"],"source":"Project Gutenberg — eBook #19412","year":null,"level":"B2","words":121533,"minutes":675,"blurb":{"tr":"Williamson çiftinin otomobil romanları dizisinden bir kitap: genç bir kadının kaleminden, İngiltere yollarında arabayla yapılan uzun bir gezi ve yol boyunca gelişen bir gönül ilişkisi. Anlatı mektup ve günlük biçiminde ilerler. Dil sohbete yakın ve rahattır, ancak yer adları ile dönemin otomobil terimleri sık geçer."},"cover":{"emoji":"⛵","hue":210},"__file":"g19412.js","__stub":true};
D["g19476"]={"id":"g19476","kind":"book","title":{"en":"A Honeymoon in Space","tr":"Uzayda Balayı"},"authors":["George Chetwynd Griffith"],"source":"Project Gutenberg — eBook #19476","year":null,"level":"C1","words":63666,"minutes":354,"blurb":{"tr":"Yirminci yüzyılın hemen başında yazılmış bir bilimkurgu. Yeni evlenmiş varlıklı bir İngiliz soylusu ile Amerikalı karısı, yerçekimini yenen bir gemiyle balayına Güneş Sistemi'nde çıkar; Ay'da, Mars'ta, Venüs'te ve dev gezegenlerin uydularında bambaşka canlılarla karşılaşırlar. Bilimsel açıklamalar dönemin ağdalı gazete diliyle yazılmış, betimlemeler uzundur."},"cover":{"emoji":"🪐","hue":210},"__file":"g19476.js","__stub":true};
D["g1952"]={"id":"g1952","kind":"book","title":{"en":"The Yellow Wallpaper","tr":"Sarı Duvar Kâğıdı"},"authors":["Charlotte Perkins Gilman"],"source":"Project Gutenberg — eBook #1952","year":null,"level":"B2","words":6150,"minutes":34,"blurb":{"tr":"Doğumdan sonra dinlenme tedavisi bahanesiyle kocası tarafından taşra evindeki bir odaya kapatılan kadın, yazması yasaklandığı halde gizlice günlük tutar. Odadaki sarı duvar kâğıdının deseninde bir kadın figürü görmeye başlar ve giderek ona saplanır. Metin çok kısa, birinci ağızdan ve kısa cümlelerle yazılmış; asıl zorluğu dönemin tıp diline ait birkaç sözcük."},"cover":{"emoji":"🕯️","hue":210},"__file":"g1952.js","__stub":true};
D["g20"]={"id":"g20","kind":"book","title":{"en":"Paradise Lost","tr":"Kayıp Cennet"},"authors":["John Milton"],"source":"Project Gutenberg — eBook #20","year":null,"level":"C2","words":79999,"minutes":444,"blurb":{"tr":"Milton'ın destanı, Şeytan'ın cennetten kovuluşuyla başlar ve Âdem ile Havva'nın yasak meyveyi yiyip cennetten çıkarılışıyla biter. Kitabın en güçlü, en çok konuşan kişisi Şeytan'dır. Metin kafiyesiz ölçülü şiirle yazılmıştır; sözcük sırası Latince gibi ters çevrilir ve tek bir cümle sayfalarca sürebilir, bu yüzden en zor İngilizce metinlerdendir."},"cover":{"emoji":"🪶","hue":210},"__file":"g20.js","__stub":true};
D["g2002"]={"id":"g2002","kind":"book","title":{"en":"Sonnets from the Portuguese","tr":"Portekizceden Soneler"},"authors":["Elizabeth Barrett Browning"],"source":"Project Gutenberg — eBook #2002","year":null,"level":"C2","words":5165,"minutes":29,"blurb":{"tr":"Elizabeth Barrett Browning'in, sonradan evleneceği şair Robert Browning'e gizlice yazdığı kırk dört soneden oluşan dizi. Çekingen bir başlangıçtan tam teslimiyete uzanan bir iç yolculuk anlatılır; aralarında çok bilinen Seni nasıl mı seviyorum sonesi de vardır. Şiir dili on dokuzuncu yüzyıla ait: eski zamirler, devrik dizeler ve alışılmadık sözcükler yoğun."},"cover":{"emoji":"🌹","hue":210},"__file":"g2002.js","__stub":true};
D["g202"]={"id":"g202","kind":"book","title":{"en":"My Bondage and My Freedom","tr":"Köleliğim ve Özgürlüğüm"},"authors":["Frederick Douglass"],"source":"Project Gutenberg — eBook #202","year":null,"level":"C1","words":135505,"minutes":753,"blurb":{"tr":"Kölelikten kaçıp Amerika'nın en tanınmış kölelik karşıtı konuşmacısı olan Frederick Douglass'ın kendi hayatını anlattığı kitap. Maryland'deki çiftlik çocukluğunu, gizlice okuma öğrenmesini, kaçışını ve sonraki mücadele yıllarını ayrıntısıyla aktarır. Dil resmi ve hitabet ağırlıklı; cümleler uzun, kelime dağarcığı geniştir."},"cover":{"emoji":"📗","hue":210},"__file":"g202.js","__stub":true};
D["g20203"]={"id":"g20203","kind":"book","title":{"en":"Autobiography of Benjamin Franklin","tr":"Benjamin Franklin'in Otobiyografisi"},"authors":["Benjamin Franklin","Frank Woodworth Pine","E. Boyd (Elmer Boyd) Smith"],"source":"Project Gutenberg — eBook #20203","year":null,"level":"C1","words":71616,"minutes":398,"blurb":{"tr":"Franklin, Boston'daki matbaacı çıraklığından başlayarak Philadelphia'da kurduğu işi, gazetesini, kütüphane ve itfaiye gibi kamu girişimlerini ve kendini düzeltmek için hazırladığı on üç erdem listesini anlatır. Amerikan kendi kendine yetme anlayışının temel metni sayılır. On sekizinci yüzyıl İngilizcesi: cümleler uzun, yazım ve büyük harf kullanımı bugünkünden farklı."},"cover":{"emoji":"📗","hue":210},"__file":"g20203.js","__stub":true};
D["g203"]={"id":"g203","kind":"book","title":{"en":"Uncle Tom's Cabin","tr":"Tom Amca'nın Kulübesi"},"authors":["Harriet Beecher Stowe"],"source":"Project Gutenberg — eBook #203","year":null,"level":"C1","words":182322,"minutes":1013,"blurb":{"tr":"Kentucky'de yaşayan köle Tom, efendisinin borçları yüzünden satılır ve güneye, gitgide daha acımasız sahiplerin eline düşer; aynı sırada genç köle Eliza oğlunu kurtarmak için buz tutmuş nehri geçip kuzeye kaçar. Roman köleliği açık bir ahlak sorunu olarak tartışır. Diyalogların çoğu güney ağzıyla ve kırık İngilizceyle yazıldığından okuması yorucudur."},"cover":{"emoji":"📗","hue":210},"__file":"g203.js","__stub":true};
D["g204"]={"id":"g204","kind":"book","title":{"en":"The innocence of Father Brown","tr":"Peder Brown'ın Masumiyeti"},"authors":["G. K. (Gilbert Keith) Chesterton"],"source":"Project Gutenberg — eBook #204","year":null,"level":"C1","words":78928,"minutes":438,"blurb":{"tr":"Ufak tefek, dalgın görünüşlü bir Katolik rahip olan Peder Brown, suçları iz sürerek değil insanın günaha nasıl sürüklendiğini anlayarak çözer. Bu ilk kitapta birbirinden bağımsız on iki öykü var ve her biri şaşırtıcı bir tersine dönüşle biter. Chesterton'ın dili benzetme ve karşıtlıklarla yüklü, cümleler süslü; öyküler kısa olsa da yavaş okumak gerekiyor."},"cover":{"emoji":"🔍","hue":210},"__file":"g204.js","__stub":true};
D["g2040"]={"id":"g2040","kind":"book","title":{"en":"Confessions of an English Opium-Eater","tr":"Bir İngiliz Afyon Tiryakisinin İtirafları"},"authors":["Thomas De Quincey"],"source":"Project Gutenberg — eBook #2040","year":null,"level":"C2","words":38560,"minutes":214,"blurb":{"tr":"Yazarın gençliğinde başlayan afyon bağımlılığını anlattığı otobiyografik bir metin. Londra sokaklarında geçirdiği sefil günleri, ilaç olarak başlayan afyonun önce verdiği hazzı, sonra kâbusa dönüşen rüyalarını sırayla anlatır. Cümleler çok uzun ve Latince kökenli kelimeler yoğun; bu listedeki en ağır İngilizce metinlerden biri."},"cover":{"emoji":"🕯️","hue":210},"__file":"g2040.js","__stub":true};
D["g205"]={"id":"g205","kind":"book","title":{"en":"Walden, and On The Duty Of Civil Disobedience","tr":"Walden ve Sivil İtaatsizlik"},"authors":["Henry David Thoreau"],"source":"Project Gutenberg — eBook #205","year":null,"level":"C2","words":116031,"minutes":645,"blurb":{"tr":"Thoreau, Massachusetts'te bir gölün kıyısına kendi elleriyle kulübe yapıp iki yıl boyunca sade ve yalnız yaşamasını anlatır; harcamalarını, çalışmasını, mevsimleri ve gözlediği doğayı ayrıntısıyla yazar. İkinci bölüm, haksız bulduğu bir devlete vergi ödemeyi reddedişini savunan ünlü denemesidir. Dil ağır ve düşünsel, cümleler uzun, göndermeler antik metinlere uzanıyor."},"cover":{"emoji":"📗","hue":210},"__file":"g205.js","__stub":true};
D["g20717"]={"id":"g20717","kind":"book","title":{"en":"The Girl on the Boat","tr":"Gemideki Kız"},"authors":["P. G. (Pelham Grenville) Wodehouse"],"source":"Project Gutenberg — eBook #20717","year":null,"level":"B2","words":67576,"minutes":375,"blurb":{"tr":"Atlantik'i geçen bir yolcu gemisinde tanıştığı Amerikalı kıza vurulan genç bir İngiliz'in başına gelenler. Kızın nişanlısı, huysuz akrabalar, şiir yazan çekingen bir kuzen ve üst üste gelen yanlış anlamalar işi iyice karıştırır. Konuşmalar hızlı ve şakalar abartılı benzetmelere dayanıyor; cümleler kısa, ama bu mizaha alışmak biraz zaman alıyor."},"cover":{"emoji":"🎭","hue":210},"__file":"g20717.js","__stub":true};
D["g20782"]={"id":"g20782","kind":"book","title":{"en":"Triplanetary","tr":"Üç Gezegen"},"authors":["E. E. (Edward Elmer) Smith"],"source":"Project Gutenberg — eBook #20782","year":null,"level":"C1","words":56920,"minutes":316,"blurb":{"tr":"Lensman dizisinin açılış kitabı. İki kadim uzaylı ırkın binlerce yıla yayılan gizli mücadelesi, Atlantis'ten Roma'ya ve insanlığın uzaya açıldığı geleceğe uzanan sahnelerle anlatılır. Kitabın ikinci yarısı gezegenler arası devriye, korsanlar ve suda yaşayan bir uzaylı halk arasındaki savaşa ayrılmış. Uydurma bilim açıklamaları uzun, cümleler kalabalık."},"cover":{"emoji":"🪐","hue":210},"__file":"g20782.js","__stub":true};
D["g209"]={"id":"g209","kind":"book","title":{"en":"The Turn of the Screw","tr":"Yürek Burgusu"},"authors":["Henry James"],"source":"Project Gutenberg — eBook #209","year":null,"level":"C2","words":40014,"minutes":222,"blurb":{"tr":"Issız bir İngiliz malikânesine iki yetim çocuğun eğitimi için gelen genç mürebbiye, kısa süre sonra evin çevresinde ölmüş iki hizmetlinin hayaletini gördüğüne inanır. Anlatı, hayaletlerin gerçek mi yoksa mürebbiyenin kuruntusu mu olduğunu bilerek belirsiz bırakır. Henry James'in cümleleri çok uzun ve araya giren yan cümlelerle bölünüyor; listedeki en zor İngilizcelerden biri."},"cover":{"emoji":"🔍","hue":210},"__file":"g209.js","__stub":true};
D["g2097"]={"id":"g2097","kind":"book","title":{"en":"The Sign of the Four","tr":"Dörtlerin İşareti"},"authors":["Arthur Conan Doyle"],"source":"Project Gutenberg — eBook #2097","year":null,"level":"B2","words":43201,"minutes":240,"blurb":{"tr":"Babası kaybolduktan sonra her yıl posta ile kendisine bir inci gönderilen Mary Morstan, Holmes'a başvurur; izler Hindistan'dan çalınmış bir hazineye ve dört adamın verdiği eski bir söze çıkar. Roman, Thames üzerinde geçen bir tekne kovalamacasıyla biter. Holmes kitapları arasında en akıcılarından; yalnız Hindistan'a ait yer ve eşya adları yabancı gelebilir."},"cover":{"emoji":"🔍","hue":210},"__file":"g2097.js","__stub":true};
D["g21"]={"id":"g21","kind":"book","title":{"en":"Three hundred Aesop’s fables","tr":"Üç Yüz Ezop Masalı"},"authors":["621? BCE-565? BCE Aesop","George Fyler Townsend"],"source":"Project Gutenberg — eBook #21","year":null,"level":"B1","words":44794,"minutes":249,"blurb":{"tr":"Çoğu birkaç satır uzunluğunda, hayvanların insan gibi konuştuğu ve sonunda bir ders çıkarıldığı üç yüz masalın toplandığı klasik derleme. Tilki ile üzüm ya da karınca ile ağustos böceği gibi bilinen hikâyelerin kaynağı burasıdır. Her masal ayrı ve kısa olduğu için istenen yerden okunabiliyor; çeviri biraz eski, öğüt cümleleri kalıplı."},"cover":{"emoji":"🐉","hue":210},"__file":"g21.js","__stub":true};
D["g2130"]={"id":"g2130","kind":"book","title":{"en":"Utopia","tr":"Utopia"},"authors":["Thomas More","Henry Morley"],"source":"Project Gutenberg — eBook #2130","year":null,"level":"C2","words":43490,"minutes":242,"blurb":{"tr":"Thomas More, gezgin bir denizcinin ağzından Utopia adlı hayali ada devletini anlatır: mülkiyetin ortak olduğu, herkesin altı saat çalıştığı, altının değersiz sayıldığı bir düzen. İlk bölüm ise dönemin İngiltere'sindeki yoksulluğu ve idam cezasını eleştirir. Latinceden çevrilen metin uzun cümleli ve tartışma üslubunda, kolay okunmaz."},"cover":{"emoji":"📗","hue":210},"__file":"g2130.js","__stub":true};
D["g2147"]={"id":"g2147","kind":"book","title":{"en":"The Works of Edgar Allan Poe — Volume 1","tr":"Edgar Allan Poe'nun Eserleri — 1. Cilt"},"authors":["Edgar Allan Poe","James Russell Lowell","Nathaniel Parker Willis"],"source":"Project Gutenberg — eBook #2147","year":null,"level":"C2","words":88661,"minutes":493,"blurb":{"tr":"Poe'nun toplu eserlerinin ilk cildi; dedektif türünün başlangıcı sayılan Morgue Sokağı Cinayetleri ve Marie Rogêt'nin Esrarı, şifre çözme üzerine kurulu Altın Böcek ile Şişede Bulunan Elyazması gibi metinleri bir araya getirir. Kitap, Lowell ve Willis'in Poe'nun hayatı üzerine yazılarıyla açılır. Sözcük dağarcığı ağır ve eskidir, cümleler uzundur; anlatıcılar sık sık Fransızca ve Latince deyişlere başvuruyor."},"cover":{"emoji":"🔍","hue":210},"__file":"g2147.js","__stub":true};
D["g2148"]={"id":"g2148","kind":"book","title":{"en":"The Works of Edgar Allan Poe — Volume 2","tr":"Edgar Allan Poe'nun Eserleri, Cilt 2"},"authors":["Edgar Allan Poe"],"source":"Project Gutenberg — eBook #2148","year":null,"level":"C2","words":96329,"minutes":535,"blurb":{"tr":"Poe'nun öykülerini toplayan çok ciltli baskının ikinci cildi. İçinde suçluluk duygusu, diri diri gömülme, çöken evler ve intikam üzerine kurulu korku öyküleriyle, modern polisiyenin habercisi sayılan akıl yürütme hikâyeleri bir arada bulunur. Poe'nun cümleleri uzun ve Latince kökenli sözcüklerle doludur; metinler kısa olsa da dil ağırdır."},"cover":{"emoji":"🔍","hue":210},"__file":"g2148.js","__stub":true};
D["g2160"]={"id":"g2160","kind":"book","title":{"en":"The Expedition of Humphry Clinker","tr":"Humphry Clinker'ın Seferi"},"authors":["T. (Tobias) Smollett"],"source":"Project Gutenberg — eBook #2160","year":null,"level":"C2","words":149029,"minutes":828,"blurb":{"tr":"Galli yaşlı bir beyefendi, kız kardeşi, yeğenleri ve hizmetkârlarından oluşan bir aile İngiltere ile İskoçya'yı gezer; gördükleri her şeyi birbirinden çok farklı gözlerle mektuplara dökerler. Roman baştan sona bu mektuplardan oluşur ve mizahı bu görüş ayrılıklarından doğar. Bazı kişiler sözcükleri bilerek yanlış yazar; 18. yüzyıl diliyle birleşince okuması çok zorlaşır."},"cover":{"emoji":"🎭","hue":210},"__file":"g2160.js","__stub":true};
