D["g43453"]={"id":"g43453","kind":"book","title":{"en":"A Pickle for the Knowing Ones","tr":"Bilenlere Bir Turşu"},"authors":["Timothy Dexter"],"source":"Project Gutenberg — eBook #43453","year":null,"level":"C2","words":12576,"minutes":70,"blurb":{"tr":"On dokuzuncu yüzyılın başında yaşamış, okuma yazması zayıf ama çok zengin bir Amerikalı tüccarın kendi bastırdığı tuhaf broşür. Dexter burada komşularından, politikacılardan ve kendi ününden söz eder; metinde neredeyse hiç noktalama yoktur, ikinci baskıya okurlar diledikleri yere serpiştirsin diye bir sayfa dolusu noktalama işareti eklemiştir. Yazım baştan sona kuraldışıdır, okuması bulmaca çözmeye benzer."},"cover":{"emoji":"🎭","hue":210},"__file":"g43453.js","__stub":true};
