D["g46276"]={"id":"g46276","kind":"book","title":{"en":"The Treasure of Pearls: A Romance of Adventures in California","tr":"İnci Hazinesi: Kaliforniya'da Bir Macera"},"authors":["Gustave Aimard","Lascelles Wraxall"],"source":"Project Gutenberg — eBook #46276","year":null,"level":"B2","words":75216,"minutes":418,"blurb":{"tr":"Fransız macera yazarı Gustave Aimard'ın Kaliforniya'da geçen romanı; burada İngilizce çevirisinden okunuyor. Değerli bir inci hazinesinin peşine düşen kişilerin sınır bölgesindeki yolculuklarını, karşılaştıkları tehlikeleri ve aralarındaki rekabeti anlatır. Çeviri metin düz ve olaya dayalıdır; cümleler orta uzunlukta, ancak coğrafya sözcükleri ve İspanyolca kökenli adlar boldur."},"cover":{"emoji":"⛵","hue":210},"__file":"g46276.js","__stub":true};
