D["g54219"]={"id":"g54219","kind":"book","title":{"en":"A Little English Gallery","tr":"Küçük Bir İngiliz Galerisi"},"authors":["Louise Imogen Guiney"],"source":"Project Gutenberg — eBook #54219","year":null,"level":"C2","words":50934,"minutes":283,"blurb":{"tr":"Amerikalı şair Louise Imogen Guiney'nin İngiliz edebiyat ve kültür tarihinden birkaç kişiyi ele aldığı deneme kitabı. Her bölüm bir yazarın ya da tarihî kişinin portresini çizer; yazar biyografik ayrıntıyla kendi beğenilerini iç içe anlatır. Kurgu değildir. Guiney'nin üslubu süslü ve göndermelerle doludur, edebiyat tarihine aşina olmayan okuru zorlar."},"cover":{"emoji":"📗","hue":210},"__file":"g54219.js","__stub":true};
