D["g55059"]={"id":"g55059","kind":"book","title":{"en":"Modern English biography, volume 1 (of 4), A-H","tr":"Modern İngiliz Biyografisi, 1. Cilt (4 ciltten), A-H"},"authors":["Frederic Boase"],"source":"Project Gutenberg — eBook #55059","year":null,"level":"C1","words":395461,"minutes":2197,"blurb":{"tr":"On dokuzuncu yüzyılın ikinci yarısında ölmüş İngilizlerin kısa yaşam öykülerini alfabetik sırayla veren dört ciltlik başvuru eserinin ilk cildi; A'dan H'ye kadar olan adları kapsar. Roman gibi baştan sona okunmak için değil, tek bir ismi aramak için kullanılır. Maddeler kısaltmalarla ve çok sıkışık bir dille yazılmıştır, akıcı düzyazı okumaya benzemez."},"cover":{"emoji":"📗","hue":210},"__file":"g55059.js","__stub":true};
