D["g55179"]={"id":"g55179","kind":"book","title":{"en":"One of the Six Hundred: A Novel","tr":"Altı Yüzlerden Biri"},"authors":["James Grant"],"source":"Project Gutenberg — eBook #55179","year":null,"level":"C1","words":163359,"minutes":908,"blurb":{"tr":"İzinli olarak evine dönen süvari subayı Newton Norcliff, ölen annesinin anısı ve kuzeni Cora'ya duyduğu karşılık bulmamış sevgiyle uğraşırken yeniden cepheye çağrılmayı bekler. Başlıktaki altı yüz, Kırım Savaşı'ndaki ünlü Hafif Süvari Hücumu'na katılanlardır. Victoria dönemi askerî romanı: cümleler uzun, alay ve rütbe adları ile savaş terimleri bol."},"cover":{"emoji":"⛵","hue":210},"__file":"g55179.js","__stub":true};
D["g553"]={"id":"g553","kind":"book","title":{"en":"Out of Time's Abyss","tr":"Zamanın Uçurumundan"},"authors":["Edgar Rice Burroughs"],"source":"Project Gutenberg — eBook #553","year":null,"level":"B2","words":35679,"minutes":198,"blurb":{"tr":"Caspak üçlemesinin son kitabı. Adada mahsur kalan bir İngiliz subayı, geceleri havada süzülen kanatlı yaratıklar tarafından kaçırılır ve onların ölülerle dolu şehrine götürülür. Kaçış planı kadar adanın tuhaf yaşam düzeninin sırrı da açıklanıyor. Kısa bir roman, cümleler basit; yalnızca uydurma yer ve halk adlarına alışmak gerekiyor."},"cover":{"emoji":"🪐","hue":210},"__file":"g553.js","__stub":true};
D["g558"]={"id":"g558","kind":"book","title":{"en":"The Thirty-Nine Steps","tr":"Otuz Dokuz Basamak"},"authors":["John Buchan"],"source":"Project Gutenberg — eBook #558","year":null,"level":"B2","words":41064,"minutes":228,"blurb":{"tr":"Londra'ya yeni dönmüş, canı sıkılan Richard Hannay, dairesinde bir cesetle karşılaşınca hem polisten hem katillerden kaçmak zorunda kalır. İskoçya kırlarında süren kovalamaca, Avrupa'yı savaşa sürükleyecek bir komployu ortaya çıkarır. Kitap kısa ve tempo yüksek; yalnız İskoç ağzıyla yazılmış birkaç konuşma yavaşlatabilir."},"cover":{"emoji":"🔍","hue":210},"__file":"g558.js","__stub":true};
D["g55987"]={"id":"g55987","kind":"book","title":{"en":"Letters of Asa Gray; Vol. 2","tr":"Asa Gray'in Mektupları, 2. Cilt"},"authors":["Asa Gray","Jane Loring Gray"],"source":"Project Gutenberg — eBook #55987","year":null,"level":"C1","words":131375,"minutes":730,"blurb":{"tr":"Harvard'lı botanikçi Asa Gray'in mektuplarından derlenen iki ciltlik kitabın ikincisi; derlemeyi eşi hazırlamıştır. Mektuplarda bitki toplama gezileri, Avrupa'daki meslektaşlarıyla yazışmaları, evrim kuramı çevresindeki tartışmalar ve dönemin bilim çevrelerine dair gözlemler var. Kişisel mektuplardan oluştuğu için kopuk ilerler, bitki adları Latincedir."},"cover":{"emoji":"🧭","hue":210},"__file":"g55987.js","__stub":true};
D["g560"]={"id":"g560","kind":"book","title":{"en":"Mr. Standfast","tr":"Bay Standfast"},"authors":["John Buchan"],"source":"Project Gutenberg — eBook #560","year":null,"level":"C1","words":128675,"minutes":715,"blurb":{"tr":"Birinci Dünya Savaşı sürerken cepheden alınan Richard Hannay, İngiltere içinde çalışan bir Alman casus ağını bulmakla görevlendirilir. Sahte bir kimlikle savaş karşıtı bir topluluğa sızar; iz onu İskoçya'ya, oradan Alp Dağları'na ve yeniden cepheye götürür. Uzun bir kitap; İskoç ağzıyla yazılmış konuşmalar ve savaş terimleri sık geçiyor."},"cover":{"emoji":"🔍","hue":210},"__file":"g560.js","__stub":true};
D["g564"]={"id":"g564","kind":"book","title":{"en":"The Mystery of Edwin Drood","tr":"Edwin Drood'un Esrarı"},"authors":["Charles Dickens"],"source":"Project Gutenberg — eBook #564","year":null,"level":"C1","words":96118,"minutes":534,"blurb":{"tr":"Katedral kasabası Cloisterham'da koro şefi John Jasper, yeğeni Edwin Drood'un nişanlısına gizli bir tutku besler. Edwin bir gece ortadan kaybolur ve şüpheler kasabaya yeni gelenlerin üzerinde toplanır. Dickens roman yarıda kalmışken öldüğü için çözüm hiçbir zaman yazılmadı. Ayrıntı yüklü uzun cümleler ve kasaba ağzıyla konuşan yan karakterler okumayı zorlaştırır."},"cover":{"emoji":"🔍","hue":210},"__file":"g564.js","__stub":true};
D["g56463"]={"id":"g56463","kind":"book","title":{"en":"Bacon's Essays, and Wisdom of the Ancients","tr":"Bacon'ın Denemeleri ve Kadimlerin Bilgeliği"},"authors":["Francis Bacon","Basil Montagu","A. (Alexander) Spiers"],"source":"Project Gutenberg — eBook #56463","year":null,"level":"C2","words":112512,"minutes":625,"blurb":{"tr":"Francis Bacon'ın kısa denemeleri hakikat, ölüm, intikam, evlilik, dostluk, para ve okumak gibi konularda yoğun ve özlü öğütler verir. Kitabın ikinci bölümü eski Yunan ve Roma mitlerini birer ahlak ve siyaset dersi olarak yorumlar. Metin on yedinci yüzyıl İngilizcesiyle yazılmış; cümleler kısa ama sözcükler eskimiş, anlamlar sıkıştırılmıştır."},"cover":{"emoji":"📗","hue":210},"__file":"g56463.js","__stub":true};
D["g57333"]={"id":"g57333","kind":"book","title":{"en":"Project Gutenberg Compilation of Short Stories by Chekhov","tr":"Çehov'dan Kısa Öyküler Derlemesi"},"authors":["Anton Pavlovich Chekhov","David Widger"],"source":"Project Gutenberg — eBook #57333","year":null,"level":"B2","words":941316,"minutes":5230,"blurb":{"tr":"Çehov'un İngilizceye çevrilmiş kısa öykülerinden hazırlanmış bir derleme. Küçük memurlar, taşra doktorları, köylüler ve mutsuz evlilikler üzerine, çoğu birkaç sayfalık anlatılar; olaylar büyümeden, ders verilmeden biter. Öyküler kısa olduğu için okumaya alışmak kolay, asıl zorluk Rus adlarının uzun biçimleri ve dönemin memurluk ile para birimi sözcükleri."},"cover":{"emoji":"📑","hue":210},"__file":"g57333.js","__stub":true};
D["g57426"]={"id":"g57426","kind":"book","title":{"en":"Baron Trump's Marvellous Underground Journey","tr":"Baron Trump'ın Olağanüstü Yeraltı Yolculuğu"},"authors":["Ingersoll Lockwood","Charles Howard Johnson"],"source":"Project Gutenberg — eBook #57426","year":null,"level":"B2","words":68919,"minutes":383,"blurb":{"tr":"Kendini beğenmiş küçük Alman asilzadesi ve sadık köpeği, eski bir el yazmasının izinde Rusya'nın kuzeyine gidip yerin altındaki dünyalara iner; orada birbirinden acayip halklarla karşılaşırlar. On dokuzuncu yüzyıl sonunun çocuklara yönelik fantastik yolculuk kitaplarından. Bölümler kısa, ama anlatıcının abartılı dili eskimiş sözcükler içeriyor."},"cover":{"emoji":"🪐","hue":210},"__file":"g57426.js","__stub":true};
D["g580"]={"id":"g580","kind":"book","title":{"en":"The Pickwick Papers","tr":"Mister Pickwick'in Maceraları"},"authors":["Charles Dickens"],"source":"Project Gutenberg — eBook #580","year":null,"level":"C1","words":99177,"minutes":551,"blurb":{"tr":"Varlıklı ve saf yürekli Bay Pickwick, kurduğu kulübün üyeleriyle İngiltere'yi dolaşıp gördüklerini not etmeye çıkar; gezi bir dizi yanlış anlaşılmaya, bir mahkemeye ve borçlular hapishanesine kadar uzanır. Uşağı Sam Weller'ın nüktedanlığı kitabın en sevilen yanıdır. Bölümler gevşek bağlı, dil şakacı; Sam'in Londra ağzı okumayı zorlaştırır."},"cover":{"emoji":"🎭","hue":210},"__file":"g580.js","__stub":true};
