D["g58866"]={"id":"g58866","kind":"book","title":{"en":"The Murder on the Links","tr":"Golf Sahasında Cinayet"},"authors":["Agatha Christie"],"source":"Project Gutenberg — eBook #58866","year":null,"level":"B2","words":65135,"minutes":362,"blurb":{"tr":"Hayatının tehlikede olduğunu yazan zengin bir adam Poirot'yu acele Fransa'ya çağırır; Poirot vardığında adam, yeni yapılan bir golf sahasının kenarında sırtından bıçaklanmış hâlde bulunmuştur. Poirot, soruşturmaya el koyan kendine fazla güvenen Fransız dedektifle bir yarışa girer. Diyalog ağırlıklı ve cümleler kısa; arada çevrilmemiş Fransızca kalıplar var."},"cover":{"emoji":"🔍","hue":210},"__file":"g58866.js","__stub":true};
