D["g5921"]={"id":"g5921","kind":"book","title":{"en":"The History of Don Quixote, Volume 1, Complete","tr":"Don Kişot, Birinci Cilt"},"authors":["Miguel de Cervantes Saavedra","Gustave Doré","John Ormsby"],"source":"Project Gutenberg — eBook #5921","year":null,"level":"C1","words":216034,"minutes":1200,"blurb":{"tr":"Şövalye romanlarını okuya okuya aklını yitiren yaşlı bir taşra soylusu, kendini gezgin şövalye ilan edip paslı bir zırhla yollara düşer; yanında köylü uşağı Sancho Panza vardır. Yel değirmenlerini dev sanmasıyla başlayan maceralar bu ilk ciltte toplanmıştır. Ormsby'nin çevirisi eski ve süslü bir İngilizceyle yapılmış, cümleler uzundur."},"cover":{"emoji":"📗","hue":210},"__file":"g5921.js","__stub":true};
D["g59828"]={"id":"g59828","kind":"book","title":{"en":"The String of Pearls; Or, The Barber of Fleet Street. A Domestic Romance.","tr":"İnci Gerdanlık: Fleet Sokağı'nın Berberi"},"authors":["James Malcolm Rymer","Thomas Peckett Prest"],"source":"Project Gutenberg — eBook #59828","year":null,"level":"C1","words":436191,"minutes":2423,"blurb":{"tr":"Fleet Sokağı'ndaki berber Sweeney Todd, dükkânına gelen varlıklı müşterileri gizli bir düzenekle ortadan kaldırır; cesetler ise yakındaki turtacıda yok edilir. Denizden dönmeyen bir sevgilinin yolladığı inci gerdanlığın izini süren Johanna, gerçeği bulmak için erkek kılığına girer. Ucuz gazete tefrikası olarak yazıldığı için dili abartılı ve melodramatiktir, ama bölümler kısadır."},"cover":{"emoji":"🔍","hue":210},"__file":"g59828.js","__stub":true};
