D["g601"]={"id":"g601","kind":"book","title":{"en":"The Monk: A Romance","tr":"Keşiş"},"authors":["M. G. (Matthew Gregory) Lewis"],"source":"Project Gutenberg — eBook #601","year":null,"level":"C2","words":137144,"minutes":762,"blurb":{"tr":"Madrid'de herkesin saygı duyduğu genç keşiş Ambrosio, manastıra giren birinin etkisiyle yeminlerinden sapar ve şehvetten cinayete, oradan şeytanla yapılan bir pazarlığa uzanan bir çöküşe sürüklenir. Yayımlandığı yıl skandal yaratmış, gotik türün en sert örneklerinden biridir. 18. yüzyıl sonunun ağdalı dili, çok uzun cümleleri ve araya giren şiirler okumayı ağırlaştırır."},"cover":{"emoji":"🕯️","hue":210},"__file":"g601.js","__stub":true};
D["g60316"]={"id":"g60316","kind":"book","title":{"en":"The Bakhtyār Nāma: A Persian Romance","tr":"Bahtiyarname: Bir Fars Hikâyesi"},"authors":["William Ouseley","W. A. (William Alexander) Clouston"],"source":"Project Gutenberg — eBook #60316","year":null,"level":"C1","words":72040,"minutes":400,"blurb":{"tr":"Ölüme mahkûm edilen genç Bahtiyar, cezasını ertelemek için hükümdara her gün bir hikâye anlatır; on vezir ise idamı çabuklaştırmak için karşı hikâyelerle yanıt verir. İç içe geçmiş masallardan kurulu bir Fars çerçeve anlatısıdır. Ouseley'in çevirisi eski üsluplu ve dipnotlarla yüklüdür, cümleler dolambaçlı ilerler."},"cover":{"emoji":"🐉","hue":210},"__file":"g60316.js","__stub":true};
