D["g61262"]={"id":"g61262","kind":"book","title":{"en":"Poirot Investigates","tr":"Poirot Soruşturuyor"},"authors":["Agatha Christie"],"source":"Project Gutenberg — eBook #61262","year":null,"level":"B2","words":52781,"minutes":293,"blurb":{"tr":"Belçikalı dedektif Hercule Poirot'nun kısa vakalarından oluşan bir öykü kitabı. Çalınan mücevherler, kaybolan insanlar, lanetli sayılan bir Mısır mezarı ve otel odalarında işlenen cinayetler, arkadaşı Hastings'in ağzından anlatılır; Poirot çözümü koşuşturarak değil, konuşarak bulur. Öyküler kısa ve dil yalın, sadece Poirot'nun araya kattığı Fransızca sözler açıklama ister."},"cover":{"emoji":"🔍","hue":210},"__file":"g61262.js","__stub":true};
