D["g6133"]={"id":"g6133","kind":"book","title":{"en":"The Extraordinary Adventures of Arsène Lupin, Gentleman-Burglar","tr":"Kibar Hırsız Arsen Lüpen'in Olağanüstü Maceraları"},"authors":["Maurice Leblanc"],"source":"Project Gutenberg — eBook #6133","year":null,"level":"B2","words":54273,"minutes":302,"blurb":{"tr":"Maurice Leblanc'ın yarattığı kibar hırsız Arsen Lüpen'in ilk öykü derlemesi. Kılık değiştirerek soygun planlayan, hapisteyken bile gazetelere mektup yollamayı beceren bu hırsız hem polisi hem de ünlü bir İngiliz dedektifi alaya alır. Öyküler birbirinden bağımsız ve kısadır; dil sadedir, yalnızca Fransızca kişi adları ve Paris semtlerinin yazımı ilk başta yavaşlatabilir."},"cover":{"emoji":"🔍","hue":210},"__file":"g6133.js","__stub":true};
