D["g67098"]={"id":"g67098","kind":"book","title":{"en":"Winnie-the-Pooh","tr":"Winnie-the-Pooh"},"authors":["A. A. (Alan Alexander) Milne","Ernest H. (Ernest Howard) Shepard"],"source":"Project Gutenberg — eBook #67098","year":null,"level":"A2","words":22076,"minutes":123,"blurb":{"tr":"Christopher Robin'in oyuncak ayısı Pooh ile arkadaşları Piglet, Eeyore, Rabbit ve Owl, Yüz Dönümlük Orman'da küçük maceralar yaşar: bal peşinde koşmak, kaybolan bir kuyruğu aramak, ziyarete gidip kapıya sıkışmak. Her bölüm kendi başına bir hikâye. Cümleler kısa ve sözcükler basit; yalnızca bazı sözcükler ayının ağzından bilerek yanlış yazılmıştır."},"cover":{"emoji":"🧸","hue":210},"__file":"g67098.js","__stub":true};
D["g674"]={"id":"g674","kind":"book","title":{"en":"Plutarch: Lives of the noble Grecians and Romans","tr":"Paralel Hayatlar: Ünlü Yunanlılar ve Romalılar"},"authors":["46-120? Plutarch","Arthur Hugh Clough"],"source":"Project Gutenberg — eBook #674","year":null,"level":"C2","words":258088,"minutes":1434,"blurb":{"tr":"Plutarkhos, ünlü Yunan ve Romalı komutanlarla devlet adamlarının yaşamlarını ikişer ikişer eşleştirerek anlatır; İskender ile Caesar, Demosthenes ile Cicero gibi. Amacı olayları sıralamaktan çok kişilerin karakterini ve ahlaki tercihlerini göstermektir. Dryden çevirisine dayanan metin çok hacimli, cümleleri uzun ve dili on yedinci yüzyıla yakındır."},"cover":{"emoji":"🐉","hue":210},"__file":"g674.js","__stub":true};
D["g6761"]={"id":"g6761","kind":"book","title":{"en":"The Adventures of Ferdinand Count Fathom — Complete","tr":"Kont Ferdinand Fathom'un Maceraları (Tam Metin)"},"authors":["T. (Tobias) Smollett"],"source":"Project Gutenberg — eBook #6761","year":null,"level":"C2","words":161738,"minutes":899,"blurb":{"tr":"18. yüzyıl Avrupa'sında şehir şehir dolaşıp kumar, sahtekârlık ve yalanla geçinen Ferdinand Fathom'un serüvenleri anlatılır; bu kez romanın merkezinde bir kahraman değil, tam bir alçak vardır. Smollett'in kalemi acımasız ve alaycıdır. Metin 18. yüzyıl İngilizcesiyle yazılmıştır: cümleler çok uzun, sözcükler eski ve Latince kökenlidir."},"cover":{"emoji":"📗","hue":210},"__file":"g6761.js","__stub":true};
D["g6768"]={"id":"g6768","kind":"book","title":{"en":"The Man Upstairs and Other Stories","tr":"Üst Kattaki Adam ve Diğer Öyküler"},"authors":["P. G. (Pelham Grenville) Wodehouse"],"source":"Project Gutenberg — eBook #6768","year":null,"level":"C1","words":99926,"minutes":555,"blurb":{"tr":"Wodehouse'un 1914'te derlediği, yirmiye yakın kısa öyküden oluşan kitap. Çoğu Londra ve New York'ta geçer; parasız ressamlar, boksla uğraşan gençler, evlenmeye çalışan delikanlılar ve aksi akrabalar şakacı bir dille anlatılır. Öyküler bağımsızdır, sırayla okumak gerekmez. Wodehouse'un mizahı benzetmelere ve dönemin argosuna dayanır; kelime dağarcığı sanıldığından geniştir."},"cover":{"emoji":"🎭","hue":210},"__file":"g6768.js","__stub":true};
D["g67979"]={"id":"g67979","kind":"book","title":{"en":"The Blue Castle: a novel","tr":"Mavi Şato"},"authors":["L. M. (Lucy Maud) Montgomery"],"source":"Project Gutenberg — eBook #67979","year":null,"level":"B2","words":69461,"minutes":386,"blurb":{"tr":"Yirmi dokuz yaşındaki Valancy Stirling, ailesinin baskısı altında renksiz bir hayat sürerken doktordan kalbinin hasta olduğunu ve fazla ömrü kalmadığını öğrenir. Bunun üzerine evden ayrılır, kasabanın dedikodusunu üzerine çeken bir adamla evlenir ve ilk kez kendi istediği gibi yaşar. Montgomery'nin yetişkinlere yazdığı ender romanlardandır. Cümleler kısa ve dil akıcıdır, yalnızca doğa betimlemeleri süslüdür."},"cover":{"emoji":"🌹","hue":210},"__file":"g67979.js","__stub":true};
