D["g69087"]={"id":"g69087","kind":"book","title":{"en":"The murder of Roger Ackroyd","tr":"Roger Ackroyd Cinayeti"},"authors":["Agatha Christie"],"source":"Project Gutenberg — eBook #69087","year":null,"level":"B2","words":70918,"minutes":394,"blurb":{"tr":"Küçük bir İngiliz köyünde zengin Roger Ackroyd çalışma odasında bıçaklanarak öldürülür; olayları köyün doktoru anlatır, soruşturmayı ise emekliye ayrıldığını sanan Hercule Poirot yürütür. Polisiye tarihinin en çok tartışılan sonlarından birine sahiptir. Christie'nin dili sade ve diyalog ağırlıklı, bölümler kısadır; İngilizce polisiyeye başlamak için uygun."},"cover":{"emoji":"🔍","hue":210},"__file":"g69087.js","__stub":true};
