D["g70175"]={"id":"g70175","kind":"book","title":{"en":"The secret of Father Brown","tr":"Peder Brown'ın Sırrı"},"authors":["G. K. (Gilbert Keith) Chesterton"],"source":"Project Gutenberg — eBook #70175","year":null,"level":"C1","words":59808,"minutes":332,"blurb":{"tr":"Kısa boylu, sessiz bir Katolik rahip olan Peder Brown'ın cinayet ve gizem öykülerinden oluşan derleme. Çerçeve bölümde Brown, suçluları nasıl bulduğunun sırrını bir konuğuna anlatır; ardından çözdüğü tuhaf vakalar sıralanır. Chesterton'ın cümleleri paradokslar ve benzetmelerle yüklü; öyküler kısa olsa da dili düşündürücü."},"cover":{"emoji":"🔍","hue":210},"__file":"g70175.js","__stub":true};
D["g70200"]={"id":"g70200","kind":"book","title":{"en":"Pen-portraits of literary women","tr":"Edebiyatçı Kadınların Kalem Portreleri"},"authors":["Helen Gray Cone","Jeannette L. (Jeannette Leonard) Gilder"],"source":"Project Gutenberg — eBook #70200","year":null,"level":"C1","words":73722,"minutes":410,"blurb":{"tr":"On dokuzuncu yüzyılın sonunda derlenmiş bir antoloji: kadın yazarlar hakkında onları tanıyan ya da inceleyen kişilerin yazdıkları, kimi zaman da yazarların kendi mektup ve günlüklerinden alınan bölümler bir araya getirilmiştir. Jane Austen, Brontë kardeşler ve George Eliot gibi isimler çağdaşlarının gözünden anlatılır. Her bölüm ayrı bir kalemden çıktığı için üslup değişir; genel olarak dil ağdalı ve dönemseldir."},"cover":{"emoji":"📗","hue":210},"__file":"g70200.js","__stub":true};
