D["g75201"]={"id":"g75201","kind":"book","title":{"en":"A farewell to arms","tr":"Silahlara Veda"},"authors":["Ernest Hemingway"],"source":"Project Gutenberg — eBook #75201","year":null,"level":"B2","words":88641,"minutes":492,"blurb":{"tr":"Birinci Dünya Savaşı'nda İtalyan cephesinde ambulans şoförlüğü yapan Amerikalı bir teğmenin, İngiliz hemşire Catherine ile yaşadığı aşkı anlatır. Bozgun, cepheden kaçış ve İsviçre'ye sığınma bölümleriyle savaşın kahramanlık süsü tek tek sökülür. Hemingway'in cümleleri çok kısa ve sözcük dağarcığı dardır; asıl zorluk arada geçen İtalyanca repliklerde ve üstü kapalı anlatımdadır."},"cover":{"emoji":"🌹","hue":210},"__file":"g75201.js","__stub":true};
D["g76"]={"id":"g76","kind":"book","title":{"en":"Adventures of Huckleberry Finn","tr":"Huckleberry Finn'in Maceraları"},"authors":["Mark Twain","E. W. (Edward Windsor) Kemble"],"source":"Project Gutenberg — eBook #76","year":null,"level":"C1","words":111575,"minutes":620,"blurb":{"tr":"Huck, sarhoş babasından kaçıp Mississippi Nehri'ne açılır; yol arkadaşı, özgürlüğünü arayan köle Jim'dir. Sal üstündeki bu yolculuk boyunca kıyı kasabalarında dolandırıcılarla, kan davalarıyla ve kendi vicdanıyla karşılaşırlar. Kitap baştan sona Huck'ın ağzından güney ağzıyla yazılmıştır; sözcükler bilerek yanlış yazıldığı için okuması zordur."},"cover":{"emoji":"⛵","hue":210},"__file":"g76.js","__stub":true};
D["g76178"]={"id":"g76178","kind":"book","title":{"en":"I am a woman","tr":"Ben Bir Kadınım"},"authors":["Ann Bannon"],"source":"Project Gutenberg — eBook #76178","year":null,"level":"B2","words":74962,"minutes":416,"blurb":{"tr":"Laura Landon, baskıcı babasından ve yarım bıraktığı üniversiteden kaçıp New York'ta Greenwich Village'a yerleşir; ev arkadaşı Marcie ile yaşarken kentin gizli bar çevresinde kendi arzularıyla yüzleşir. 1959'da ucuz cep kitabı olarak basılmış bir lezbiyen aşk romanıdır. Cümleler kısa ve dil bugünküne yakın, ancak dönemin argosu ve gündelik konuşma kalıpları zorlayabilir."},"cover":{"emoji":"🌹","hue":210},"__file":"g76178.js","__stub":true};
D["g766"]={"id":"g766","kind":"book","title":{"en":"David Copperfield","tr":"David Copperfield"},"authors":["Charles Dickens"],"source":"Project Gutenberg — eBook #766","year":null,"level":"C1","words":354195,"minutes":1968,"blurb":{"tr":"Babasını doğmadan kaybeden David'in çocukluğundan olgunluğuna uzanan hayatı: sert bir üvey baba, çocuk işçilik yılları, Yarmouth'taki balıkçı ailesi ve sürekli borç içindeki Bay Micawber. Dickens'ın en kişisel romanı sayılır. Cümleler uzun ve dolambaçlı, kitap hacimli; ayrıca birçok karakter kendi şivesiyle konuşuyor."},"cover":{"emoji":"📗","hue":210},"__file":"g766.js","__stub":true};
D["g76639"]={"id":"g76639","kind":"book","title":{"en":"Eloisa","tr":"Julie ya da Yeni Heloise"},"authors":["Jean-Jacques Rousseau","W. (William) Kenrick"],"source":"Project Gutenberg — eBook #76639","year":null,"level":"C2","words":307354,"minutes":1708,"blurb":{"tr":"Varlıklı bir İsviçre ailesinin kızı Julie ile ona ders veren öğretmeni arasındaki yasak aşkın, baştan sona mektuplarla anlatıldığı çok uzun bir roman. Sınıf farkı evlenmelerini engelleyince hikâye tutku ile erdem, aşk ile aile düzeni arasındaki çatışmaya döner. Metin 18. yüzyılda yapılmış bir İngilizce çeviridir. Olay az, düşünce çoktur; cümleler çok uzun ve sözcükler eskidir."},"cover":{"emoji":"🌹","hue":210},"__file":"g76639.js","__stub":true};
